<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientBackchannelTokenDeliveryModeOptions;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientBackchannelTokenDeliveryModeAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientBackchannelTokenDeliveryModeAccessor trait.
 *
 * Covers null default, string/VO assignment via withBackchannelTokenDeliveryMode,
 * getBackchannelTokenDeliveryMode/backchannelTokenDeliveryMode accessors, and isBackchannelTokenDeliveryModeChanged with/without original.
 */
class TrustedClientBackchannelTokenDeliveryModeAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withBackchannelTokenDeliveryMode creates a new instance with the BackchannelTokenDeliveryMode set
     * from a string value, and getBackchannelTokenDeliveryMode returns the primitive string.
     */
    public function testWithBackchannelTokenDeliveryModeFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientBackchannelTokenDeliveryModeAccessorUnitTest();

        // Act
        $result = $holder->withBackchannelTokenDeliveryMode(TrustedClientBackchannelTokenDeliveryModeOptions::POLL);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TrustedClientBackchannelTokenDeliveryModeOptions::POLL, $result->getBackchannelTokenDeliveryMode());
    }
    /**
     * Asserts that withbackchannelTokenDeliveryMode has access to the value object
     * from a string value, and getBackchannelTokenDeliveryMode returns the primitive string.
     */
    public function testWithBackchannelTokenDeliveryModeFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientBackchannelTokenDeliveryModeAccessorUnitTest();

        // Act
        $result = $holder->withBackchannelTokenDeliveryMode(TrustedClientBackchannelTokenDeliveryModeOptions::POLL);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TrustedClientBackchannelTokenDeliveryModeOptions::POLL, $result->backchannelTokenDeliveryMode()->value());
    }
    public function testChangedBackchannelTokenDeliveryMode(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientBackchannelTokenDeliveryModeAccessorUnitTest();
        $original = $holder->withBackchannelTokenDeliveryMode(TrustedClientBackchannelTokenDeliveryModeOptions::POLL);
        $same = $holder->withBackchannelTokenDeliveryMode(TrustedClientBackchannelTokenDeliveryModeOptions::POLL);
        $modified = $holder->withBackchannelTokenDeliveryMode(TrustedClientBackchannelTokenDeliveryModeOptions::PING);

        // Act
        $unchanged = $holder->isBackchannelTokenDeliveryModeChanged();
        $withSame = $original->isBackchannelTokenDeliveryModeChanged($same);
        $withDiferent = $original->isBackchannelTokenDeliveryModeChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientBackchannelTokenDeliveryModeAccessorUnitTest
{
    use TrustedClientBackchannelTokenDeliveryModeAccessor;
}
